            Node second = reverse(slow.next);
            Node p = head;
            Node r = second;
            while (r != null) {
                if (p.val != r.val) {
                    palindrome = false;
                    break;
                }
                p = p.next;
                r = r.next;
            }
            slow.next = reverse(second);
