        PriorityQueue<Node> pq = new PriorityQueue<>((x, y) -> Integer.compare(x.val, y.val));
        for (int i = 0; i < k; i++) {
            int len = Integer.parseInt(sc.next());
            Node head = build(sc, len);
            if (head != null) {
                pq.add(head);
            }
        }
        Node dummy = new Node(0);
        Node tail = dummy;
        while (!pq.isEmpty()) {
            Node node = pq.poll();
            tail.next = node;
            tail = node;
            if (node.next != null) {
                pq.add(node.next);
            }
        }
        tail.next = null;
        System.out.println(listString(dummy.next));
    }
}

class Node {
    int val;
    Node next;

    Node(int val) {
        this.val = val;
    }
}

