import java.util.*;

public class Main {
    static void unlink(DNode node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    static void insertFront(DNode head, DNode node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int c = Integer.parseInt(sc.next());
        int q = Integer.parseInt(sc.next());
        Map<Integer, DNode> map = new HashMap<>();
        DNode head = new DNode(0, 0);
        DNode tail = new DNode(0, 0);
        head.next = tail;
        tail.prev = head;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String cmd = sc.next();
            int key = Integer.parseInt(sc.next());
            if (cmd.equals("GET")) {
                DNode node = map.get(key);
                if (node == null) {
                    out.append("-1\n");
                } else {
                    unlink(node);
                    insertFront(head, node);
                    out.append(node.value).append("\n");
                }
            } else {
                int value = Integer.parseInt(sc.next());
                if (c == 0) {
                    continue;
                }
                DNode node = map.get(key);
                if (node != null) {
                    node.value = value;
                    unlink(node);
                    insertFront(head, node);
                } else {
                    if (map.size() == c) {
                        DNode lru = tail.prev;
                        unlink(lru);
                        map.remove(lru.key);
                    }
                    node = new DNode(key, value);
                    map.put(key, node);
                    insertFront(head, node);
                }
            }
        }
        System.out.print(out);
    }
}

class DNode {
    final int key;
    int value;
    DNode prev;
    DNode next;

    DNode(int key, int value) {
        this.key = key;
        this.value = value;
    }
}
